-- Упражнения книги 19, глава 6 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 6, 'la6-subtree-write', 0, 'func', 'Запись в cgroup.subtree_control', 'Модель записи в cgroup.subtree_control. Напишите функцию apply_subtree_control(controllers, current, request): controllers - содержимое cgroup.controllers этой группы (имена через пробел, порядок важен), current - текущее содержимое её cgroup.subtree_control (имена через пробел, может быть пустой строкой), request - то, что записывают: токены через пробел, каждый ''+имя'' или ''-имя''. Токены применяются по порядку. Запись отклоняется целиком (ничего не меняется), если токен не начинается с + или - , имя пустое или имени нет в controllers. Верните новое содержимое cgroup.subtree_control строкой: включённые контроллеры через один пробел в том порядке, в каком они перечислены в controllers; при отклонении верните None. ''-имя'' для не включённого контроллера допустимо и ничего не делает; пустой request ничего не меняет.', 'def apply_subtree_control(controllers, current, request):
    pass
', 'Сначала проверьте все токены, потом применяйте; результат собирайте обходом controllers.split().', '{"func": "apply_subtree_control", "tests": [{"args": ["cpuset cpu io memory pids", "", "+cpu +memory"], "expected": "cpu memory"}, {"args": ["cpuset cpu io memory pids", "cpu memory", "-cpu +io"], "expected": "io memory"}, {"args": ["cpuset cpu io memory pids", "cpu", "+hugetlb"], "expected": null}, {"args": ["cpu memory", "cpu", "cpu"], "expected": null}, {"args": ["cpu memory", "cpu memory", "-memory -memory"], "expected": "cpu"}, {"args": ["cpu memory", "", ""], "expected": ""}, {"args": ["cpu memory", "memory", "+cpu -cpu"], "expected": "memory"}, {"args": ["", "", "+cpu"], "expected": null}, {"args": ["cpu io", "cpu", "-"], "expected": null}, {"args": ["cpu io", "cpu", "+cpu +io -cpu"], "expected": "io"}, {"args": ["cpuset cpu io memory pids", "memory", "-io"], "expected": "memory"}, {"args": ["cpuset cpu io memory pids", "cpu", "+pids +memory +bogus"], "expected": null}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 6, 'la6-validate-tree', 1, 'func', 'Проверка дерева групп', 'Напишите функцию validate_tree(root_controllers, cgroups): root_controllers - список контроллеров, доступных в корне; cgroups - словарь путь -> {"procs": число процессов прямо в группе, "subtree": список контроллеров из её cgroup.subtree_control}. Пути вида "/", "/a", "/a/b"; родитель "/a/b" - это "/a", родитель "/a" - это "/". Группа, которой нет в словаре, считается пустой: ни процессов, ни включённых контроллеров. Найдите нарушения и верните отсортированный список кортежей (путь, причина). Причины: "internal-process" - у не корневой группы procs > 0 и непустой subtree; "not-available:ИМЯ" - контроллер ИМЯ включён в subtree корня, но его нет в root_controllers; "not-enabled-in-parent:ИМЯ" - контроллер ИМЯ включён в subtree не корневой группы, но не включён в subtree её родителя. Одна группа может нарушать несколько правил, каждое нарушение - отдельный кортеж. Сортируйте кортежи обычным сравнением.', 'def validate_tree(root_controllers, cgroups):
    pass
', 'Для каждого пути определите родителя (rsplit(''/'', 1)); для корня «родитель» - root_controllers.', '{"func": "validate_tree", "tests": [{"args": [["cpu", "memory", "pids"], {"/": {"procs": 120, "subtree": ["cpu", "memory"]}, "/system.slice": {"procs": 0, "subtree": ["memory"]}, "/system.slice/a.service": {"procs": 3, "subtree": []}}], "expected": []}, {"args": [["cpu", "memory"], {"/": {"procs": 0, "subtree": ["cpu"]}, "/a": {"procs": 2, "subtree": ["cpu"]}}], "expected": [{"__tuple__": ["/a", "internal-process"]}]}, {"args": [["cpu", "memory"], {"/": {"procs": 0, "subtree": ["cpu"]}, "/a": {"procs": 0, "subtree": ["memory"]}}], "expected": [{"__tuple__": ["/a", "not-enabled-in-parent:memory"]}]}, {"args": [["cpu"], {"/": {"procs": 0, "subtree": ["cpu", "io"]}}], "expected": [{"__tuple__": ["/", "not-available:io"]}]}, {"args": [["cpu", "io"], {"/": {"procs": 5, "subtree": ["cpu"]}, "/a": {"procs": 1, "subtree": ["cpu", "io"]}, "/a/b": {"procs": 0, "subtree": ["cpu"]}}], "expected": [{"__tuple__": ["/a", "internal-process"]}, {"__tuple__": ["/a", "not-enabled-in-parent:io"]}]}, {"args": [["cpu"], {"/": {"procs": 0, "subtree": ["cpu"]}, "/a/b": {"procs": 0, "subtree": ["cpu"]}}], "expected": [{"__tuple__": ["/a/b", "not-enabled-in-parent:cpu"]}]}, {"args": [["cpu"], {}], "expected": []}, {"args": [["cpu", "memory"], {"/": {"procs": 3, "subtree": ["cpu", "memory"]}, "/x": {"procs": 4, "subtree": []}, "/y": {"procs": 0, "subtree": ["memory", "cpu"]}, "/y/z": {"procs": 1, "subtree": ["cpu"]}}], "expected": [{"__tuple__": ["/y/z", "internal-process"]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 6, 'la6-cpu-max', 2, 'func', 'CPUQuota в cpu.max', 'Модель перевода свойств юнита в файл cpu.max. Напишите функцию cpu_max(assignments): assignments - список строк ''Имя=Значение'', которые применяются по порядку (позднее присваивание побеждает). Учитываются только CPUQuota и CPUQuotaPeriodSec, остальные имена игнорируются. CPUQuota - число с необязательной десятичной частью и знаком %, например ''150%'' или ''12.5%''; пустое значение убирает квоту. CPUQuotaPeriodSec - целое число с суффиксом us, ms или s (''500us'', ''20ms'', ''1s''); пустое значение возвращает период по умолчанию 100ms. Период в микросекундах ограничивается диапазоном от 1000 до 1000000. Квота в микросекундах = процент * период / 100, округлённая вверх до целого; если она получилась меньше 1000, она равна 1000. Верните строку для cpu.max: ''квота период'', а без квоты ''max период''. Используйте дроби (fractions.Fraction), а не float.', 'def cpu_max(assignments):
    pass
', 'Fraction(''12.5'') точен; округление вверх: -((-x) // 1) или math.ceil. Суффиксы: us=1, ms=1000, s=1000000.', '{"func": "cpu_max", "tests": [{"args": [[]], "expected": "max 100000"}, {"args": [["CPUQuota=50%"]], "expected": "50000 100000"}, {"args": [["CPUQuota=250%"]], "expected": "250000 100000"}, {"args": [["CPUQuota=50%", "CPUQuotaPeriodSec=10ms"]], "expected": "5000 10000"}, {"args": [["CPUQuota=20%", "CPUQuota="]], "expected": "max 100000"}, {"args": [["CPUQuotaPeriodSec=2s", "CPUQuota=100%"]], "expected": "1000000 1000000"}, {"args": [["CPUQuota=0.5%"]], "expected": "1000 100000"}, {"args": [["CPUQuota=12.5%", "CPUQuotaPeriodSec=500us"]], "expected": "1000 1000"}, {"args": [["Nice=5", "CPUQuota=33.3%"]], "expected": "33300 100000"}, {"args": [["CPUQuota=33.3333%"]], "expected": "33334 100000"}, {"args": [["CPUQuota=10%", "CPUQuotaPeriodSec=50ms", "CPUQuotaPeriodSec="]], "expected": "10000 100000"}, {"args": [["CPUQuota=150.05%", "CPUQuotaPeriodSec=1ms"]], "expected": "1501 1000"}, {"args": [["CPUQuotaPeriodSec=20ms"]], "expected": "max 20000"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 6, 'la6-cpu-stat-delta', 3, 'func', 'Разность двух cpu.stat', 'Напишите функцию cpu_stat_delta(before, after): before и after - содержимое файла cpu.stat одной группы в два момента (строки ''ключ число''). Верните кортеж (periods, throttled, throttled_pct, cpu_ms): periods - прирост nr_periods, throttled - прирост nr_throttled, throttled_pct - доля periods, в которых группу придерживали, в процентах (100 * throttled / periods), округлённая функцией round до одного знака, а при periods == 0 число 0.0; cpu_ms - прирост usage_usec, целочисленно разделённый на 1000. Отсутствующие ключи считаются нулём (в группе без контроллера cpu нет строк nr_periods и nr_throttled). Прирост меньше нуля (счётчики сбросились) считается нулём.', 'def cpu_stat_delta(before, after):
    pass
', 'Разберите каждый текст в словарь через split(); прирост - max(0, after.get(k, 0) - before.get(k, 0)).', '{"func": "cpu_stat_delta", "tests": [{"args": ["usage_usec 8233514\nuser_usec 6120339\nsystem_usec 2113175\nnr_periods 410\nnr_throttled 37\nthrottled_usec 1840221\nnr_bursts 0\nburst_usec 0\n", "usage_usec 12733514\nuser_usec 9420339\nsystem_usec 3313175\nnr_periods 530\nnr_throttled 74\nthrottled_usec 3640221\nnr_bursts 0\nburst_usec 0\n"], "expected": {"__tuple__": [120, 37, 30.8, 4500]}}, {"args": ["usage_usec 8233514\nuser_usec 6120339\nsystem_usec 2113175\nnr_periods 410\nnr_throttled 37\nthrottled_usec 1840221\nnr_bursts 0\nburst_usec 0\n", "usage_usec 8233514\nuser_usec 6120339\nsystem_usec 2113175\nnr_periods 410\nnr_throttled 37\nthrottled_usec 1840221\nnr_bursts 0\nburst_usec 0\n"], "expected": {"__tuple__": [0, 0, 0.0, 0]}}, {"args": ["usage_usec 1000000\nuser_usec 700000\nsystem_usec 300000\n", "usage_usec 4500999\nuser_usec 3000000\nsystem_usec 1500999\n"], "expected": {"__tuple__": [0, 0, 0.0, 3500]}}, {"args": ["", "usage_usec 12733514\nuser_usec 9420339\nsystem_usec 3313175\nnr_periods 530\nnr_throttled 74\nthrottled_usec 3640221\nnr_bursts 0\nburst_usec 0\n"], "expected": {"__tuple__": [530, 74, 14.0, 12733]}}, {"args": ["usage_usec 12733514\nuser_usec 9420339\nsystem_usec 3313175\nnr_periods 530\nnr_throttled 74\nthrottled_usec 3640221\nnr_bursts 0\nburst_usec 0\n", "usage_usec 8233514\nuser_usec 6120339\nsystem_usec 2113175\nnr_periods 410\nnr_throttled 37\nthrottled_usec 1840221\nnr_bursts 0\nburst_usec 0\n"], "expected": {"__tuple__": [0, 0, 0.0, 0]}}, {"args": ["usage_usec 0\nnr_periods 0\nnr_throttled 0\n", "usage_usec 999\nnr_periods 8\nnr_throttled 5\n"], "expected": {"__tuple__": [8, 5, 62.5, 0]}}, {"args": ["nr_periods 100\nnr_throttled 0\nusage_usec 5000\n", "nr_periods 300\nnr_throttled 3\nusage_usec 6999999\n"], "expected": {"__tuple__": [200, 3, 1.5, 6994]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 6, 'la6-effective-limit', 4, 'func', 'Эффективный предел в дереве', 'Напишите функцию effective_limit(limits, path): limits - словарь путь -> строка из файла memory.max (или memory.high) этой группы: либо ''max'' (без предела), либо число байтов десятичной записью. Пути вида ''/'', ''/a'', ''/a/b''. Группы, которых нет в словаре, считаются ''max''. Эффективный предел группы path - наименьший из пределов самой группы и всех её предков вплоть до корня ''/''. Верните кортеж (предел, путь): предел - целое число байтов и путь той группы, чей предел действует; если среди нескольких групп предел одинаков, берите ту, что ближе к корню. Если пределов нет нигде, верните (''max'', '''').', 'def effective_limit(limits, path):
    pass
', 'Постройте цепочку предков от корня к path и пройдите по ней, обновляя минимум только при строгом уменьшении.', '{"func": "effective_limit", "tests": [{"args": [{"/machine.slice": "2147483648", "/machine.slice/vm1.scope": "10737418240"}, "/machine.slice/vm1.scope"], "expected": {"__tuple__": [2147483648, "/machine.slice"]}}, {"args": [{"/machine.slice": "max", "/machine.slice/vm1.scope": "1073741824"}, "/machine.slice/vm1.scope"], "expected": {"__tuple__": [1073741824, "/machine.slice/vm1.scope"]}}, {"args": [{}, "/a/b/c"], "expected": {"__tuple__": ["max", ""]}}, {"args": [{"/a": "100", "/a/b": "100", "/a/b/c": "50"}, "/a/b"], "expected": {"__tuple__": [100, "/a"]}}, {"args": [{"/a": "100", "/a/b": "100", "/a/b/c": "50"}, "/a/b/c"], "expected": {"__tuple__": [50, "/a/b/c"]}}, {"args": [{"/a": "100", "/x": "5"}, "/a/b"], "expected": {"__tuple__": [100, "/a"]}}, {"args": [{"/": "4096", "/a": "8192"}, "/a"], "expected": {"__tuple__": [4096, "/"]}}, {"args": [{"/a": "300"}, "/"], "expected": {"__tuple__": ["max", ""]}}, {"args": [{"/a": "max", "/a/b": "max"}, "/a/b"], "expected": {"__tuple__": ["max", ""]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 6, 'la6-memory-verdicts', 5, 'func', 'Что случилось с памятью группы', 'Напишите функцию memory_verdicts(before, after): before и after - содержимое файла memory.events одной группы в два момента (строки ''ключ число''; ключи low, high, max, oom, oom_kill, а в новых ядрах ещё oom_group_kill; отсутствующий ключ считается нулём). Для каждого ключа возьмите прирост (отрицательный считайте нулём) и верните список вердиктов в этом порядке: ''group-kill'' - прирост oom_group_kill больше нуля; ''oom-killed'' - прирост oom_kill больше нуля; ''oom-no-kill'' - прирост oom больше нуля, а прирост oom_kill равен нулю; ''hit-max'' - прирост max больше нуля; ''throttled-high'' - прирост high больше нуля; ''reclaimed-low'' - прирост low больше нуля. Если ничего не выросло, верните пустой список.', 'def memory_verdicts(before, after):
    pass
', 'Разберите оба текста в словари и посчитайте прирост по ключам; затем проверьте условия по порядку.', '{"func": "memory_verdicts", "tests": [{"args": ["low 0\nhigh 0\nmax 0\noom 0\noom_kill 0\n", "low 0\nhigh 0\nmax 0\noom 0\noom_kill 0\n"], "expected": []}, {"args": ["low 0\nhigh 10\nmax 2\noom 0\noom_kill 0\n", "low 0\nhigh 140\nmax 16\noom 3\noom_kill 2\n"], "expected": ["oom-killed", "hit-max", "throttled-high"]}, {"args": ["low 0\nhigh 0\nmax 0\noom 0\noom_kill 0\n", "low 0\nhigh 0\nmax 4\noom 1\noom_kill 0\n"], "expected": ["oom-no-kill", "hit-max"]}, {"args": ["low 0\nhigh 0\nmax 0\noom 0\noom_kill 0\noom_group_kill 0\n", "low 0\nhigh 0\nmax 0\noom 1\noom_kill 3\noom_group_kill 1\n"], "expected": ["group-kill", "oom-killed"]}, {"args": ["low 5\nhigh 0\nmax 0\noom 0\noom_kill 0\n", "low 9\nhigh 1\nmax 0\noom 0\noom_kill 0\n"], "expected": ["throttled-high", "reclaimed-low"]}, {"args": ["low 0\nhigh 0\nmax 0\noom 7\noom_kill 7\n", "low 0\nhigh 0\nmax 0\noom 1\noom_kill 2\n"], "expected": []}, {"args": ["high 4\nmax 1\n", "high 4\nmax 2\noom 1\noom_kill 1\n"], "expected": ["oom-killed", "hit-max"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 6, 'la6-cgls-procs', 6, 'func', 'Процессы по группам из systemd-cgls', 'Напишите функцию procs_by_cgroup(text): text - вывод systemd-cgls. Первая строка ''Control group /:'' пропускается. Дальше дерево: имя группы либо процесс; каждая строка начинается с префикса из символов ''│'', ''├'', ''└'', ''─'' и пробела, длина префикса, делённая на 2, - глубина (у корня ''-.slice'' префикса нет, глубина 0). Процесс - это строка, где после префикса идёт число (PID), за которым пробел или конец строки; процесс относится к ближайшей выше группе с глубиной на 1 меньше. Всё остальное после префикса - имя группы. Путь группы: корень ''-.slice'' даёт ''/'', остальные - ''/'' плюс имена групп от глубины 1 до неё через ''/''. Верните словарь путь -> список PID (целые числа в порядке появления) только для групп, в которых есть процессы напрямую.', 'def procs_by_cgroup(text):
    pass
', 'Ведите стек имён по глубине: names[depth] = имя; процесс глубины d относится к names[d-1].', '{"func": "procs_by_cgroup", "tests": [{"args": ["Control group /:\n-.slice\n├─user.slice\n│ └─user-1000.slice\n│   └─session-3.scope\n│     ├─1500 sshd: alex [priv]\n│     └─1520 -bash\n├─init.scope\n│ └─1 /sbin/init\n└─system.slice\n  ├─sshd.service\n  │ └─800 sshd: /usr/sbin/sshd -D [listener]\n  └─cron.service\n    └─700 /usr/sbin/cron -f\n"], "expected": {"/user.slice/user-1000.slice/session-3.scope": [1500, 1520], "/init.scope": [1], "/system.slice/sshd.service": [800], "/system.slice/cron.service": [700]}}, {"args": ["Control group /:\n-.slice\n├─machine.slice\n│ ├─machine-qemu\\x2d1\\x2dweb.scope\n│ │ └─libvirt\n│ │   ├─2201 /usr/bin/qemu-system-x86_64 -name guest=web\n│ │   └─2209 /usr/bin/qemu-system-x86_64 -name guest=web\n│ └─machine-qemu\\x2d2\\x2ddb.scope\n│   └─libvirt\n│     └─2310 /usr/bin/qemu-system-x86_64 -name guest=db\n└─system.slice\n  ├─libvirtd.service\n  │ ├─1100 /usr/sbin/libvirtd --timeout 120\n  │ └─1101 /usr/sbin/dnsmasq --conf-file=/var/lib/libvirt/dnsmasq/default.conf\n  └─chronyd.service\n    └─950 /usr/sbin/chronyd\n"], "expected": {"/machine.slice/machine-qemu\\x2d1\\x2dweb.scope/libvirt": [2201, 2209], "/machine.slice/machine-qemu\\x2d2\\x2ddb.scope/libvirt": [2310], "/system.slice/libvirtd.service": [1100, 1101], "/system.slice/chronyd.service": [950]}}, {"args": ["Control group /:\n-.slice\n"], "expected": {}}, {"args": ["Control group /:\n-.slice\n└─system.slice\n  └─a.service\n    └─5\n"], "expected": {"/system.slice/a.service": [5]}}, {"args": ["Control group /:\n-.slice\n├─1000.slice\n│ └─42 prog 7 8\n└─system.slice\n  └─7 init\n"], "expected": {"/1000.slice": [42], "/system.slice": [7]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 6, 'la6-cgtop-own-memory', 7, 'func', 'Собственная память групп из systemd-cgtop', 'Напишите функцию top_own_memory(output, n): output - вывод ''systemd-cgtop -b -n 1'' (первая строка - заголовок, её пропустите). В каждой следующей строке колонки через пробелы: путь группы, Tasks, %CPU, Memory, Input/s, Output/s; значение ''-'' означает, что данных нет. Memory - число с необязательной единицей B, K, M, G или T (степени 1024; десятичная часть допустима, ''B'' или её отсутствие - байты), например ''1.5G'', ''512.0M'', ''0B''. Память группы в cgtop включает память её дочерних групп. Для каждой группы (кроме корня ''/'') со значением Memory посчитайте собственную память: Memory группы минус сумма Memory её прямых дочерних групп из этого же вывода (дочерняя без данных считается нулём; родитель группы ''/a/b'' - это ''/a''); результат не меньше нуля. Верните n групп с наибольшей собственной памятью, как список кортежей (путь, байты) с целым числом байтов, по убыванию, а при равенстве по пути. Байты = значение * множитель, число в тестах точное.', 'def top_own_memory(output, n):
    pass
', 'Сначала словарь путь -> байты, затем для каждого пути вычтите детей; сортировка по ключу (-байты, путь).', '{"func": "top_own_memory", "tests": [{"args": ["CGroup                                  Tasks   %CPU   Memory  Input/s Output/s\n/                                         412   18.2     5.0G        -        -\n/system.slice                             120    9.4     2.5G        -        -\n/system.slice/mysql.service                38    8.1     1.5G        -        -\n/system.slice/sshd.service                  3    0.0    12.5M        -        -\n/user.slice                                90    4.0     1.0G        -        -\n/user.slice/user-1000.slice                90    4.0     1.0G        -        -\n", 3], "expected": [{"__tuple__": ["/system.slice/mysql.service", 1610612736]}, {"__tuple__": ["/user.slice/user-1000.slice", 1073741824]}, {"__tuple__": ["/system.slice", 1060634624]}]}, {"args": ["CGroup                                  Tasks   %CPU   Memory  Input/s Output/s\n/                                         412   18.2     5.0G        -        -\n/system.slice                             120    9.4     2.5G        -        -\n/system.slice/mysql.service                38    8.1     1.5G        -        -\n/system.slice/sshd.service                  3    0.0    12.5M        -        -\n/user.slice                                90    4.0     1.0G        -        -\n/user.slice/user-1000.slice                90    4.0     1.0G        -        -\n", 1], "expected": [{"__tuple__": ["/system.slice/mysql.service", 1610612736]}]}, {"args": ["CGroup                                  Tasks   %CPU   Memory  Input/s Output/s\n/                                         300   40.0     8.0G        -        -\n/machine.slice                            100   35.0     6.0G        -        -\n/machine.slice/machine-qemu\\x2d1\\x2da.scope   50   20.0     3.0G        -        -\n/machine.slice/machine-qemu\\x2d2\\x2db.scope   50   15.0     2.5G        -        -\n/system.slice                              90    2.0   512.0M        -        -\n/system.slice/a.service                    10    1.0         -        -        -\n/init.scope                                 1    0.0     3.5M        -        -\n", 4], "expected": [{"__tuple__": ["/machine.slice/machine-qemu\\x2d1\\x2da.scope", 3221225472]}, {"__tuple__": ["/machine.slice/machine-qemu\\x2d2\\x2db.scope", 2684354560]}, {"__tuple__": ["/machine.slice", 536870912]}, {"__tuple__": ["/system.slice", 536870912]}]}, {"args": ["CGroup                                  Tasks   %CPU   Memory  Input/s Output/s\n/                                         300   40.0     8.0G        -        -\n/machine.slice                            100   35.0     6.0G        -        -\n/machine.slice/machine-qemu\\x2d1\\x2da.scope   50   20.0     3.0G        -        -\n/machine.slice/machine-qemu\\x2d2\\x2db.scope   50   15.0     2.5G        -        -\n/system.slice                              90    2.0   512.0M        -        -\n/system.slice/a.service                    10    1.0         -        -        -\n/init.scope                                 1    0.0     3.5M        -        -\n", 0], "expected": []}, {"args": ["CGroup                                  Tasks   %CPU   Memory  Input/s Output/s\n/                                         300   40.0     8.0G        -        -\n/machine.slice                            100   35.0     6.0G        -        -\n/machine.slice/machine-qemu\\x2d1\\x2da.scope   50   20.0     3.0G        -        -\n/machine.slice/machine-qemu\\x2d2\\x2db.scope   50   15.0     2.5G        -        -\n/system.slice                              90    2.0   512.0M        -        -\n/system.slice/a.service                    10    1.0         -        -        -\n/init.scope                                 1    0.0     3.5M        -        -\n", 10], "expected": [{"__tuple__": ["/machine.slice/machine-qemu\\x2d1\\x2da.scope", 3221225472]}, {"__tuple__": ["/machine.slice/machine-qemu\\x2d2\\x2db.scope", 2684354560]}, {"__tuple__": ["/machine.slice", 536870912]}, {"__tuple__": ["/system.slice", 536870912]}, {"__tuple__": ["/init.scope", 3670016]}]}, {"args": ["CGroup Tasks %CPU Memory Input/s Output/s\n", 3], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 6, 'la6-props-to-files', 8, 'func', 'Свойства юнита в файлы cgroup', 'Модель перевода свойств юнита в содержимое файлов группы. Напишите функцию props_to_files(props, ram, pid_max, devices): props - список строк ''Имя=Значение'', применяются по порядку; ram - объём памяти хоста в байтах; pid_max - число для процентов в TasksMax; devices - словарь путь устройства -> ''MAJ:MIN''. Верните словарь имя файла -> содержимое (строка). Правила. Размер: целое число с необязательным суффиксом K, M, G, T (степени 1024) или ''infinity''. MemoryLow, MemoryHigh, MemoryMax -> memory.low, memory.high, memory.max: размер, либо ''N%'' = ram * N // 100, либо ''infinity'' -> ''max''. MemorySwapMax -> memory.swap.max: размер или ''infinity'' -> ''max'' (процентов нет). CPUWeight -> cpu.weight: целое число как есть; ''idle'' даёт файл cpu.idle со значением ''1'' (и не даёт cpu.weight). IOWeight -> io.weight: ''default N''. TasksMax -> pids.max: целое число, ''N%'' = pid_max * N // 100, или ''infinity'' -> ''max''. IOReadBandwidthMax, IOWriteBandwidthMax, IOReadIOPSMax, IOWriteIOPSMax -> строки файла io.max: значение ''УСТРОЙСТВО ПРЕДЕЛ'', предел - целое число с суффиксом K, M, G, T (степени 1000) или ''infinity'' -> ''max''; ключи rbps, wbps, riops, wiops. Для каждого устройства одна строка ''MAJ:MIN ключ=предел ...'' с ключами в порядке rbps, wbps, riops, wiops (только заданные), строки в файле сортируются по (major, minor) как числам и соединяются через перевод строки. Повторное присваивание того же свойства (для устройства - того же свойства и устройства) заменяет предыдущее. Пустое значение сбрасывает свойство (для четырёх свойств io.max - все их записи); сброшенное свойство в результат не попадает. Остальные имена игнорируются.', 'def props_to_files(props, ram, pid_max, devices):
    pass
', 'Держите словарь single[имя] и словарь io[(устройство, ключ)]; сброс - удаление записей; в конце соберите файлы.', '{"func": "props_to_files", "tests": [{"args": [["MemoryMax=2G", "MemoryHigh=1536M", "CPUWeight=200", "TasksMax=512"], 8589934592, 4194304, {}], "expected": {"memory.max": "2147483648", "memory.high": "1610612736", "cpu.weight": "200", "pids.max": "512"}}, {"args": [["MemoryMax=25%", "MemoryLow=1G", "MemoryMax=50%"], 8589934592, 4194304, {}], "expected": {"memory.max": "4294967296", "memory.low": "1073741824"}}, {"args": [["MemoryMax=infinity", "MemorySwapMax=0", "TasksMax=10%"], 1000, 200000, {}], "expected": {"memory.max": "max", "memory.swap.max": "0", "pids.max": "20000"}}, {"args": [["CPUWeight=idle", "IOWeight=50", "MemoryHigh=64K", "MemoryHigh="], 1, 1, {}], "expected": {"cpu.idle": "1", "io.weight": "default 50"}}, {"args": [["CPUWeight=idle", "CPUWeight=300", "TasksMax=infinity"], 1, 1, {}], "expected": {"cpu.weight": "300", "pids.max": "max"}}, {"args": [["IOReadBandwidthMax=/dev/vda 10M", "IOWriteBandwidthMax=/dev/vda 5M", "IOReadIOPSMax=/dev/vdb 2K"], 1, 1, {"/dev/vda": "252:0", "/dev/vdb": "8:16"}], "expected": {"io.max": "8:16 riops=2000\n252:0 rbps=10000000 wbps=5000000"}}, {"args": [["IOWriteIOPSMax=/dev/sda 500", "IOReadBandwidthMax=/dev/sda 1G", "IOReadBandwidthMax=/dev/sda infinity", "IOWriteIOPSMax=/dev/sdb 7"], 1, 1, {"/dev/sda": "8:0", "/dev/sdb": "8:16"}], "expected": {"io.max": "8:0 rbps=max wiops=500\n8:16 wiops=7"}}, {"args": [["IOReadBandwidthMax=/dev/sda 1M", "IOWriteBandwidthMax=/dev/sda 2M", "IOReadBandwidthMax=", "CPUQuota=50%", "Nice=3"], 1, 1, {"/dev/sda": "8:0"}], "expected": {"io.max": "8:0 wbps=2000000"}}, {"args": [[], 1, 1, {}], "expected": {}}, {"args": [["IOWriteBandwidthMax=/dev/a 1M", "IOWriteBandwidthMax="], 1, 1, {"/dev/a": "8:0"}], "expected": {}}, {"args": [["IOReadIOPSMax=/dev/a 1", "IOReadIOPSMax=/dev/b 2", "IOReadIOPSMax=/dev/c 3"], 1, 1, {"/dev/a": "10:0", "/dev/b": "9:5", "/dev/c": "9:10"}], "expected": {"io.max": "9:5 riops=2\n9:10 riops=3\n10:0 riops=1"}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 6, 'la6-unit-cgroup-path', 9, 'func', 'Путь группы юнита', 'Модель размещения юнитов систем-ди в дереве групп. Напишите функцию unit_cgroup(unit, slice): unit - имя юнита, slice - значение Slice= или пустая строка, если не задано. Имя слайса из слов через дефис описывает путь от корня: ''a-b-c.slice'' лежит в ''a-b.slice'', тот в ''a.slice'', тот в корне; корневой слайс называется ''-.slice'' и его путь ''/''. Путь самого слайса: ''/a.slice/a-b.slice/a-b-c.slice''. Если unit сам заканчивается на .slice, его путь вычисляется только по его имени, slice игнорируется. Для остальных юнитов (.service, .scope и т. д.) путь = путь слайса + ''/'' + имя юнита (в корне - просто ''/'' + имя). Если slice пустой: служба-экземпляр (имя вида ''шаблон@экземпляр.service'') попадает в слайс ''system-шаблон.slice'', остальные юниты - в ''system.slice''. Верните строку пути. Дефисы внутри имён юнитов (не слайсов) не имеют значения.', 'def unit_cgroup(unit, slice):
    pass
', 'Путь слайса: разбейте имя без .slice по ''-'' и накапливайте ''a'', ''a-b'', ... с суффиксом .slice.', '{"func": "unit_cgroup", "tests": [{"args": ["sshd.service", ""], "expected": "/system.slice/sshd.service"}, {"args": ["getty@tty1.service", ""], "expected": "/system.slice/system-getty.slice/getty@tty1.service"}, {"args": ["docker-3f2a.scope", "system.slice"], "expected": "/system.slice/docker-3f2a.scope"}, {"args": ["machine-qemu\\x2d1\\x2dvm1.scope", "machine.slice"], "expected": "/machine.slice/machine-qemu\\x2d1\\x2dvm1.scope"}, {"args": ["user-1000.slice", ""], "expected": "/user.slice/user-1000.slice"}, {"args": ["-.slice", ""], "expected": "/"}, {"args": ["app.service", "-.slice"], "expected": "/app.service"}, {"args": ["db.service", "tenant-a-gold.slice"], "expected": "/tenant.slice/tenant-a.slice/tenant-a-gold.slice/db.service"}, {"args": ["system-getty.slice", "web.slice"], "expected": "/system.slice/system-getty.slice"}, {"args": ["worker@1.service", "web.slice"], "expected": "/web.slice/worker@1.service"}, {"args": ["my-app.service", ""], "expected": "/system.slice/my-app.service"}, {"args": ["backup.timer", ""], "expected": "/system.slice/backup.timer"}]}');
